use std::rc::Rc;

#[derive(Clone, Debug, Default)]
pub struct PersistentVector<T> {
    tail: Option<Rc<Node<T>>>,
    len: usize,
}

#[derive(Debug)]
struct Node<T> {
    value: T,
    prev: Option<Rc<Node<T>>>,
}

impl<T> PersistentVector<T> {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn push_back(&self, value: T) -> Self {
        Self {
            tail: Some(Rc::new(Node {
                value,
                prev: self.tail.clone(),
            })),
            len: self.len + 1,
        }
    }

    pub fn size(&self) -> usize {
        self.len
    }
}

#[cfg(test)]
mod tests {
    use super::PersistentVector;

    #[test]
    fn push_back_returns_a_new_vector() {
        let base = PersistentVector::new();
        let one = base.push_back(1);
        let two = one.push_back(2);

        assert_eq!(base.size(), 0);
        assert_eq!(one.size(), 1);
        assert_eq!(two.size(), 2);
    }
}

